BEGIN;
-- F38 acceptance: finalized bank proof uses the retained F32 state; approved budget versions are explicit.
CREATE OR REPLACE FUNCTION encova_finance_export_readiness(date_from DATE,cutoff DATE) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE statement JSONB;ar JSONB;ap JSONB;cash JSONB;r JSONB;rolls JSONB:='{}'::jsonb;kind TEXT;bank_count INTEGER;missing_banks INTEGER;missing_cash INTEGER;bank_issues JSONB;bank_proofs JSONB;deferred_issues INTEGER;clearing NUMERIC;closed_count INTEGER;ready BOOLEAN;BEGIN
 statement:=public.encova_finance_statement_readiness(date_from,cutoff,1);
 ar:=public.encova_finance_ageing_report('AR',cutoff,'',1,1,false,'ALL')->'reconciliation';ap:=public.encova_finance_ageing_report('AP',cutoff,'',1,1,false,'ALL')->'reconciliation';cash:=public.encova_finance_cash_flow_report(date_from,cutoff,'',1);
 FOREACH kind IN ARRAY ARRAY['FUNDING','LOANS','INVESTMENTS','ASSETS','ADVANCES'] LOOP r:=public.encova_finance_rollforward_report(kind,DATE '0001-01-01',cutoff,'',1,1)->'reconciliation';rolls:=rolls||jsonb_build_object(kind,r);END LOOP;
 WITH banks AS MATERIALIZED(SELECT b.id,b.name,b."glAccountId",r.id AS review_id FROM public."FinanceCashAccount" b LEFT JOIN public."FinanceReconciliation" r ON r."cashAccountId"=b.id AND r."cutoffDate"=cutoff AND r.state='FINALIZED' WHERE b.active OR EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=b."glAccountId" AND e."postingDate"<=cutoff))
 SELECT count(*),count(*) FILTER(WHERE review_id IS NULL),coalesce(jsonb_agg(jsonb_build_object('cashAccountId',id,'name',name,'issue','FINAL_BANK_RECONCILIATION_REQUIRED') ORDER BY id) FILTER(WHERE review_id IS NULL),'[]'::jsonb),coalesce(jsonb_agg(jsonb_build_object('cashAccountId',id,'reconciliationId',review_id) ORDER BY id) FILTER(WHERE review_id IS NOT NULL),'[]'::jsonb) INTO bank_count,missing_banks,bank_issues,bank_proofs FROM banks;
 SELECT count(*) INTO missing_cash FROM public."FinanceAccount" a WHERE a."controlType"='CASH' AND EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=a.id AND e."postingDate"<=cutoff) AND NOT EXISTS(SELECT 1 FROM public."FinanceCashAccount" b WHERE b."glAccountId"=a.id);
 SELECT count(*) INTO deferred_issues FROM public."FinanceAccount" a WHERE a."controlType"='DEFERRED_REVENUE' AND coalesce((SELECT sum(l.credit-l.debit) FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=a.id AND e."postingDate"<=cutoff),0)<>coalesce((SELECT sum(v.amount) FROM public."FinanceDeferredRevenueEvent" v JOIN public."FinanceInvoiceLine" l ON l.id=v."invoiceLineId" WHERE l."deferredAccountId"=a.id AND v."effectiveDate"<=cutoff),0);
 SELECT coalesce(sum(abs(balance)),0) INTO clearing FROM public.encova_finance_statement_balances(cutoff) WHERE "controlType"='OPENING_CLEARING';
 SELECT count(*) INTO closed_count FROM public."FinancePeriod" WHERE state='CLOSED' AND daterange("startDate","endDate",'[]') && daterange(date_from,cutoff,'[]');
 ready:=(statement->>'finalExportEligible')::boolean AND(ar->>'ready')::boolean AND(ap->>'ready')::boolean AND(cash->>'classificationReady')::boolean AND missing_banks=0 AND missing_cash=0 AND deferred_issues=0 AND clearing=0 AND closed_count=0 AND cutoff<=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Karachi')::date AND NOT EXISTS(SELECT 1 FROM jsonb_each(rolls)x WHERE NOT(x.value->>'ready')::boolean);
 RETURN jsonb_build_object('finalEligible',ready,'scope','Full company book, presentation, bank, AR/AP, deferred revenue, roll-forward and cash-component checks; never reduced by display filters','presentation',statement,'receivables',ar,'payables',ap,'rollforwards',rolls,'cashFlow',jsonb_build_object('classificationReady',cash->'classificationReady','unclassifiedCount',cash->'unclassifiedCount','difference',cash->'difference','componentDigest',cash#>'{metadata,filters,componentDigest}'),'banks',jsonb_build_object('total',bank_count,'missing',missing_banks,'missingCashMasters',missing_cash,'issues',(SELECT coalesce(jsonb_agg(v),'[]'::jsonb) FROM(SELECT value AS v FROM jsonb_array_elements(bank_issues) LIMIT 25)b),'proofs',bank_proofs),'deferredControlIssueCount',deferred_issues,'openingClearingBalance',round(clearing,2)::text,'closedPeriodCount',closed_count,'futureCutoff',cutoff>(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Karachi')::date);
END $$;
CREATE OR REPLACE FUNCTION encova_finance_export_capture(actor UUID,report_type TEXT,filters JSONB,export_mode TEXT) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE first_page JSONB;part JSONB;rows JSONB;readiness JSONB;date_from DATE;cutoff DATE;pages INTEGER;n INTEGER;BEGIN
 first_page:=public.encova_finance_export_page(actor,report_type,filters,1);IF (first_page->>'total')::integer>2000 THEN RAISE EXCEPTION 'FINANCE_EXPORT_LIMIT' USING ERRCODE='P0001';END IF;
 date_from:=(first_page#>>'{metadata,from}')::date;cutoff:=(first_page#>>'{metadata,to}')::date;IF date_from IS NULL OR cutoff IS NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 readiness:=public.encova_finance_export_readiness(date_from,cutoff);
 IF report_type='BUDGET_VARIANCE' THEN readiness:=readiness||jsonb_build_object('approvedBudgetAvailable',first_page->'budget' IS NOT NULL AND first_page->'budget'<>'null'::jsonb,'budgetMappingAvailable',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(first_page->'items') x WHERE NOT(x->>'mappingAvailable')::boolean),'finalEligible',(readiness->>'finalEligible')::boolean AND first_page->'budget' IS NOT NULL AND first_page->'budget'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(first_page->'items') x WHERE NOT(x->>'mappingAvailable')::boolean));END IF;
 rows:=coalesce(first_page->'items','[]'::jsonb);pages:=CASE WHEN report_type='BUDGET_VARIANCE' THEN 1 ELSE coalesce((first_page->>'pages')::integer,1) END;
 IF pages>80 THEN RAISE EXCEPTION 'FINANCE_EXPORT_LIMIT' USING ERRCODE='P0001';END IF;
 FOR n IN 2..pages LOOP part:=public.encova_finance_export_page(actor,report_type,filters,n);rows:=rows||(part->'items');END LOOP;
 IF jsonb_array_length(rows) IS DISTINCT FROM(first_page->>'total')::integer THEN RAISE EXCEPTION 'FINANCE_EXPORT_INCONSISTENT' USING ERRCODE='P0001';END IF;
 RETURN jsonb_build_object('schemaVersion',1,'reportType',report_type,'filters',filters,'mode',export_mode,'readiness',readiness,'report',jsonb_set(first_page,'{items}',rows),'rowCount',jsonb_array_length(rows),'frozen',true);
END $$;
COMMIT;
